import heapq


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: dict[str, bool] = {}
        self._priority_map = {name: idx for idx, name in enumerate(self.PRIORITIES)}
        self._ticket_counter = 0
        self._tickets: dict[int, dict] = {}
        # Min-heap elements: (sort_key, ticket_id)
        # where sort_key = (-is_vip, -priority_value, creation_order)
        self._queue: list[tuple[tuple[int, int, int], int]] = []

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        """Open a ticket; returns its id."""
        if priority not in self._priority_map:
            raise ValueError(f"Invalid priority: {priority}")

        self._ticket_counter += 1
        ticket_id = self._ticket_counter
        is_vip = self._customers.get(customer, False)

        ticket_data = {
            "id": ticket_id,
            "customer": customer,
            "title": title,
            "priority": priority,
            "order": ticket_id,
            "status": "queued",  # Possible statuses: "queued", "in_progress", "closed"
        }
        self._tickets[ticket_id] = ticket_data

        sort_key = (-int(is_vip), -self._priority_map[priority], ticket_id)
        heapq.heappush(self._queue, (sort_key, ticket_id))
        return ticket_id

    def next_ticket(self) -> int | None:
        """Take the ticket that should be handled next out of the queue; None if the queue is empty."""
        while self._queue:
            _, ticket_id = heapq.heappop(self._queue)
            ticket = self._tickets.get(ticket_id)
            if ticket and ticket["status"] == "queued":
                ticket["status"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise KeyError(f"Ticket {ticket_id} does not exist.")
        self._tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        if ticket_id not in self._tickets:
            raise KeyError(f"Ticket {ticket_id} does not exist.")

        ticket = self._tickets[ticket_id]
        if ticket["status"] == "closed":
            raise ValueError(f"Ticket {ticket_id} is closed and cannot be reopened.")

        if ticket["status"] != "queued":
            ticket["status"] = "queued"
            is_vip = self._customers.get(ticket["customer"], False)
            sort_key = (-int(is_vip), -self._priority_map[ticket["priority"]], ticket["order"])
            heapq.heappush(self._queue, (sort_key, ticket_id))
